function pasteAttributeSelection(){const target=selectedAudio?P.audioClips.find(c=>c.id===selectedAudio):current(),source=clipboard?.items?.find(v=>v.kind==='video'||v.kind==='audio')?.data;if(!source||!target)return toast('コピー元と貼り付け先のクリップを選んでください。');const audioOnly=target.kind==='audio'||source.kind==='audio';const groups=audioOnly?[['audio','音量・ミュート・音声フェード']]:[['color','色・ルック'],['crop','スケール・位置'],['motion','速度・補間・手ぶれ補正'],['visual','不透明度・映像フェード'],['audio','音量・ミュート・音声フェード']];modal(head('属性だけをペースト')+'<p class="small-note">素材・配置・IN / OUTは変更しません。速度を移すと長さは変わりますが、他のクリップは移動しません。</p>'+groups.map(([key,label])=>'<label style="display:block;padding:12px"><input type="checkbox" data-attribute="'+key+'" checked> '+label+'</label>').join('')+'<p><button id="selectAllAttributes">すべて選択</button> <button id="clearAttributes">選択解除</button></p><button id="applyAttributes">選択した属性を適用</button>');$('#selectAllAttributes').onclick=()=>Array.from(document.querySelectorAll('[data-attribute]'),e=>e.checked=true);$('#clearAttributes').onclick=()=>Array.from(document.querySelectorAll('[data-attribute]'),e=>e.checked=false);$('#applyAttributes').onclick=()=>{const keys=Array.from(document.querySelectorAll('[data-attribute]:checked'),e=>e.dataset.attribute),next=structuredClone(target);if(!pasteAttributes(next,source,keys))return toast('適用できる属性を選んでください。');mutate(()=>{for(const key of Object.keys(target))delete target[key];Object.assign(target,next)});$('#modal').close();syncVideo(true);toast('属性を適用しました。元に戻す操作で取り消せます。')}}
function pasteSelection(duplicate=false){const source=duplicate?selectedItems():clipboard?.items;if(!source?.length)return;const base=Math.min(...source.map(v=>v.start)),at=duplicate?Math.max(...source.map(v=>v.start+v.span)):time,newIds=[];mutate(()=>{for(const item of source){const start=at+(item.start-base),copy={...structuredClone(item.data),id:uid(),start};if(item.kind==='video'&&P.clips.length<200){P.clips.push(copy);if(item.linked&&P.audioClips.length<200){const audio={...structuredClone(item.linked),id:uid(),sourceClip:copy.id,start,linked:true};P.audioClips.push(audio);copy.audioDetached=audio.id}selected=copy.id}else if(item.kind==='audio'&&P.audioClips.length<200){copy.linked=false;copy.sourceClip=null;P.audioClips.push(copy);selectedAudio=copy.id;tab='sound'}else if(item.kind==='effect'&&P.effects.length<20){P.effects.push(copy);selectedEffect=copy.id;tab='fx'}else if(item.kind==='text'&&P.texts.length<20){copy.end=start+item.span;P.texts.push(copy);selectedText=copy.id;tab='text'}newIds.push(copy.id)}selectedTimeline.clear();newIds.forEach(id=>selectedTimeline.add(id))});seek(at);toast(`${newIds.length}項目を${duplicate?'複製':'貼り付け'}ました。`)}

const intentHints={'HIGH FASHION':'静止を長く。動きに強いコントラストを。',RAW:'揺れも、不完全な瞬間も残す。',CINEMATIC:'滑らかな時間と、落ち着いた動き。',CLUB:'動きのピークと、短い間隔を拾う。',DOCUMENTARY:'長い間と自然な流れを尊重する。'};
