function slider(key,label,value,min,max,step=1,unit=''){return`<div class="control-label"><label for="ctl-${key}">${label}</label><span class="control-number"><input id="out-${key}" data-control-number="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${Number(value).toFixed(step<1?2:0)}"><i>${unit}</i></span></div><input type="range" id="ctl-${key}" data-control="${key}" min="${min}" max="${max}" step="${step}" value="${value}">`}
function option(v,text,sel){return`<option value="${v}" ${sel===v?'selected':''}>${text}</option>`}
function selectControl(key,label,value,options){return`<div class="control-label"><label for="ctl-${key}">${label}</label></div><select id="ctl-${key}" data-control="${key}">${options.map(([v,t])=>option(v,t,value)).join('')}</select>`}
