bindTimelineMarquee({root:$('#timelineContent'),guide:$('#selectionMarquee'),getSelected:()=>selectedTimeline,preview:(ids,elements)=>{replaceTimelineSelection(ids,false);paintTimelineSelection(ids,elements);status(`${ids.length}項目を範囲選択中`)},finish:ids=>{replaceTimelineSelection(ids);render();status(`${ids.length}項目を選択しました。ドラッグでまとめて移動できます。`)},cancel:ids=>{replaceTimelineSelection(ids);paintTimelineSelection()},click:event=>{replaceTimelineSelection([]);const track=event.target.closest('.video-track,.editable-audio,.fx-track');if(track?.classList.contains('video-track'))activeLayer=track.id==='videoTrackTop'?2:track.id==='videoTrackUpper'?1:0;else if(track?.classList.contains('editable-audio')){activeAudioLayer=+track.id.replace('audioTrack','');tab='sound'}paintTimelineSelection();renderInspector();const rect=$('#timelineContent').getBoundingClientRect();seek(clamp((event.clientX-rect.left)/Math.max(1,rect.width)*Math.max(duration(),.001),0,duration())).then(renderTimeline)}});

function step(direction){let row=previewRow();if(!row)return;let c=row.clip,m=mediaOf(c);if(c.gap)return seek(time+direction/30);let s=sourceOffset(time-row.start,c)+direction/(m?.fps||30);seek(row.start+outputOffset(clamp(s,0,c.out-c.in),c));status(m?.rateMode==='VFR'?'VFR素材のフレーム送りは平均FPS基準です。':'フレーム送り')}
function shortcuts(){modal(head('操作ガイド')+`<div class="keyboard-grid">${[['タイムラインの細かさ','2本指でピンチ'],['指定位置の操作','Mac／Windows：右クリック'],['レイヤー横断の複数選択','空白部からドラッグして囲む'],['再生 / 停止','Space'],['後ろへ1秒','J'],['停止','K'],['前へ1秒','L'],['IN / OUT','I / O'],['再生ヘッドで分割','S'],['コピー / 切り取り','⌘/Ctrl C · ⌘/Ctrl X'],['貼り付け / 複製','⌘/Ctrl V · ⌘/Ctrl D'],['属性だけをペースト','⌘/Ctrl Shift V'],['削除・他のクリップは固定','Delete'],['前詰め削除','Shift Delete'],['フレーム送り','← / →'],['元に戻す','⌘/Ctrl Z'],['やり直し','⌘/Ctrl Shift Z'],['プロジェクト保存','⌘/Ctrl S']].map(([a,b])=>`<span>${a}</span><kbd>${b}</kbd>`).join('')}</div><p class="small-note">クリップをクリックして再生ヘッドを置き、分割またはSキーを押します。速度ランプは分割後も元のカーブを保持します。</p>`)}$('#shortcuts').onclick=shortcuts;
