const keymap={Space:()=>play(),KeyJ:()=>seek(time-1),KeyK:pause,KeyL:()=>seek(time+1),KeyI:()=>trimEdge('in'),KeyO:()=>trimEdge('out'),KeyS:split,ArrowLeft:()=>step(-1),ArrowRight:()=>step(1)};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#timelineContext').hidden){hideTimelineContext();return}if($('#modal').open||busy)return;if((e.metaKey||e.ctrlKey)&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){const actions={KeyC:()=>copySelection(),KeyX:()=>copySelection(true),KeyV:()=>e.shiftKey?pasteAttributeSelection():pasteSelection(),KeyD:()=>pasteSelection(true),KeyY:()=>undo(true)};if(actions[e.code]){e.preventDefault();actions[e.code]();return}}if(e.metaKey||e.ctrlKey){if(e.code==='KeyS'){e.preventDefault();saveFile();return}if(e.code==='KeyZ'&&!/INPUT|TEXTAREA/.test(e.target.tagName)){e.preventDefault();undo(e.shiftKey);return}}if($('#modal').open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||busy)return;if(e.key==='?'){shortcuts();return}if(e.code==='Backspace'||e.code==='Delete'){e.preventDefault();remove(e.shiftKey);return}if(keymap[e.code]){e.preventDefault();keymap[e.code]()}});
