async function deviceCheck(){if(busy)return;busy=true;cancelled=false;pause();progressModal('端末の書き出しテスト');try{const r=await fetch('device-test.mp4');if(!r.ok)throw Error('テスト素材を読み込めません。');const file=new File([await r.blob()],'device-test.mp4',{type:'video/mp4'});const m={id:'device-check',name:file.name,width:160,height:90,duration:1,fps:30,audio:true,hdr:false};const p=project();p.name='Device check';p.media=[m];p.clips=[{...clip(m),speed:.5,endSpeed:2,curve:'ease-in-out'}];p.aspect='9:16';p.clips[0].color={...lookPresets.COLD};const freeze=frozenClip(p,p.clips[0].id,.2,.3);freeze.fadeIn=.1;freeze.fadeOut=.1;p.effects=[{id:uid(),type:'flash',start:0,duration:.16,strength:1},{id:uid(),type:'black-out',start:Math.max(0,total(p)-.2),duration:.2,strength:1}];const extracted=detachAudio(p,p.clips[0].id,0);if(extracted){for(let k=1;k<4;k++)p.audioClips.push({...structuredClone(extracted),id:uid(),layer:k,audio:{...extracted.audio,volume:.15}})}p.clips.push({...structuredClone(freeze),id:uid(),layer:1,opacity:.4});p.texts=[{id:uid(),text:'MOTION',start:0,end:total(p),font:'Sans',align:'center',size:72,x:.5,y:.8,opacity:1,motion:'rise',motionDuration:.2,fadeIn:.15,fadeOut:.15}];const result=await renderOnDevice(p,[{id:m.id,file}],{preview:true,signal:operationAbort.signal,onProgress:progress});result.test=true;showDeviceResult(result,p.name,{modal,head,esc,status});await deleteRender(result.path);status('端末テスト成功：映像・音声の生成と全尺検証が完了しました。テスト用ファイルは自動で整理しました。')}catch(e){errorModal(e,deviceCheck)}finally{busy=false;jobID=null}}


