 if($('#toggleAudioLink'))$('#toggleAudioLink').onclick=()=>{const clip=a(),next=!clip.linked;mutate(()=>setAudioLinked(P,clip,next));toast(next?'映像との連動を再開しました。':'連動を解除しました。音声を独立して編集できます。')};
