 if($('#audioLoop'))$('#audioLoop').onchange=e=>mutate(()=>{a().loop=e.target.checked;if(!a().loop)a().out=Math.min(a().out,mediaOf(a()).duration);if(a().out<=a().in)a().in=0});
 $$('[data-audionum]').forEach(el=>el.onchange=()=>{const c=a(),key=el.dataset.audionum,v=clamp(el.value,0,key==='start'||c.loop?86400:mediaOf(c).duration);if(key==='in'&&v>=c.out||key==='out'&&v<=c.in)return toast('INはOUTより前にしてください。');mutate(()=>c[key]=v)});
