 $$('[data-trackname]').forEach(el=>el.onchange=()=>mutate(()=>P.audioTracks[+el.dataset.trackname].name=el.value.trim().slice(0,24)||'A'+(+el.dataset.trackname+1)));
 for(const key of ['mute','solo'])$$('[data-track'+key+']').forEach(el=>el.onclick=()=>mutate(()=>{const t=P.audioTracks[+el.dataset['track'+key]];t[key]=!t[key]}));
 $$('[data-trackvolume]').forEach(el=>{let recorded=false;el.onpointerdown=()=>{pause();checkpoint();recorded=true};el.oninput=()=>{if(!recorded){pause();checkpoint();recorded=true}P.audioTracks[+el.dataset.trackvolume].volume=clamp(el.value,0,2);audioPreview.sync(P,time,false,linkURL);save()};el.onchange=()=>{recorded=false;render()}});
