function renderAudioTimeline(dur,width){
 const rows=audioSequence(P);let transaction,oldFuture;
 for(const layer of [0,1,2,3]){
 const track=$('#audioTrack'+layer),head=$('#audioLabel'+layer),trackState=P.audioTracks[layer];track.classList.toggle('active-layer',activeAudioLayer===layer);head.title=`A${layer+1} · ${trackState.name} · ${Math.round(trackState.volume*100)}%`;head.classList.toggle('is-muted',!!trackState.mute);const mute=head.querySelector('[data-trackmute]'),volume=head.querySelector('[data-trackvolume]');mute?.classList.toggle('selected',!!trackState.mute);mute?.setAttribute('aria-pressed',String(!!trackState.mute));if(volume&&document.activeElement!==volume)volume.value=trackState.volume;
 track.innerHTML=rows.filter(r=>r.layer===layer).map(r=>`<div class="clip-block audio-clip ${selectedTimeline.has(r.clip.id)||selectedAudio===r.clip.id?'selected':''}" data-clip="${r.clip.id}" role="button" tabindex="0" aria-label="A${layer+1} ${esc(assetName(mediaOf(r.clip)))}" style="left:${r.start/Math.max(dur,.001)*100}%;width:${r.duration/Math.max(dur,.001)*100}%"><span>${r.clip.linked?`🔗 `:""}${esc(assetName(mediaOf(r.clip)))}</span><small>${r.duration.toFixed(2)}s · ${r.clip.audio.mute?'MUTE':Math.round(r.clip.audio.volume*100)+'%'}</small><span data-edge="in" class="trim-handle trim-in"></span><span data-edge="out" class="trim-handle trim-out"></span></div>`).join('');
 track.onpointerdown=e=>{if(!e.target.closest('[data-clip]')){activeAudioLayer=layer;selected=null;selectedAudio=null;tab='sound';seek((e.clientX-track.getBoundingClientRect().left)/width*(dur||30));render()}};
 bindTimeline({root:track,rows,duration:dur,media:c=>c.loop?{...mediaOf(c),duration:86400}:mediaOf(c),snap:()=>snapping,
 select:(id,event)=>{chooseTimeline('audio',id,event);renderInspector();$$('.audio-clip').forEach(el=>el.classList.toggle('selected',selectedTimeline.has(el.dataset.clip)))},
 groupRows:()=>rows.filter(r=>selectedTimeline.has(r.clip.id)),
 groupOthers:()=>timelineMoveItems().filter(v=>v.kind!=='audio'),timelineRoot:$('#timelineContent'),
 begin:()=>{pause();transaction=serial();oldFuture=[...future];checkpoint()},
 finish:(t,changed=true)=>{if(changed){let linked=false;for(const a of P.audioClips)if(selectedTimeline.has(a.id)&&a.linked){const v=linkedVideo(P,a);if(v)syncLinkedAudio(P,v);linked=true}if(linked)toast('映像と連動中です。独立して動かす場合はSOUNDで連動を解除してください。');save();render()}else{seek(t);render()}},
 cancel:()=>{if(transaction){P=sanitize(JSON.parse(transaction));history.pop();future=oldFuture;if(!P.audioClips.some(c=>c.id===selectedAudio))selectedAudio=null;render()}},
 duplicate:row=>{if(P.audioClips.length>=200)return row;const copy={...structuredClone(row.clip),id:uid(),start:row.start,linked:false,sourceClip:null};P.audioClips.push(copy);return{...row,clip:copy}},
  preview:(c,edge,didSnap,spacing)=>{const span=timing(c).duration;showTimelineSnap(didSnap?{snapped:true,target:c.start}:null);showSpacingGuide(spacing,{kind:'audio',layer:c.layer||0,start:c.start,span});status('A'+(c.layer+1)+' · '+format(c.start)+' · '+span.toFixed(2)+'秒'+(spacing?.spacing?' · 等間隔':''))},
 getLayer:y=>[0,1,2,3].find(k=>{const r=$('#audioTrack'+k).getBoundingClientRect();return y>=r.top&&y<=r.bottom})
 });
 track.ondragover=e=>{if(!e.dataTransfer.types.includes('application/x-pve-media'))return;e.preventDefault();e.dataTransfer.dropEffect='copy';track.classList.add('drop-target')};track.ondragleave=e=>{if(!track.contains(e.relatedTarget))track.classList.remove('drop-target')};track.ondrop=e=>{e.preventDefault();track.classList.remove('drop-target');const rect=track.getBoundingClientRect(),at=snapTimelinePlacement((e.clientX-rect.left)/Math.max(1,rect.width)*Math.max(dur,.001)).start;placeDraggedAssets(draggedAssetIds(e.dataTransfer),at,'audio',layer)};
 track.querySelectorAll('[data-clip]').forEach(el=>el.onkeydown=e=>{if(e.key==='Enter'){chooseTimeline('audio',el.dataset.clip,e);render();e.preventDefault()}});
 }
}
function splitAudio(){const c=P.audioClips.find(c=>c.id===selectedAudio);if(c?.linked){const v=linkedVideo(P,c);if(v){selected=v.id;selectedAudio=null;return split()}}const r=audioSequence(P).find(r=>r.clip===c);if(!r||time<=r.start+.001||time>=r.end-.001)return toast('音声クリップの途中に再生ヘッドを置いてください。');const at=time;mutate(()=>{const right=splitClip(c,c.in+sourceOffset(time-r.start,c));if(right){P.audioClips.splice(P.audioClips.indexOf(c)+1,0,right);selectedAudio=right.id}});toast(`${format(at)} で音声を分割しました。`)}
function trimAudio(edge){const c=P.audioClips.find(c=>c.id===selectedAudio),r=audioSequence(P).find(r=>r.clip===c);if(!r||time<=r.start||time>=r.end)return;const source=c.in+sourceOffset(time-r.start,c);mutate(()=>{c[edge]=source;if(edge==='in')c.start=time})}

$('#timelineScroll').addEventListener('scroll',()=>{hideTimelineContext();$('.track-labels-inner').style.transform='translateY(-'+$('#timelineScroll').scrollTop+'px)'},{passive:true});
$('#inspectorExpand').onclick=()=>{document.body.classList.remove('media-expanded');const on=document.body.classList.toggle('inspector-expanded');$('#inspectorExpand').setAttribute('aria-pressed',String(on));$('#inspectorExpand').ariaLabel=on?'編集画面へ戻す':'設定パネルを広げる';fitKey='';requestAnimationFrame(()=>{fit();draw()})};
function fitViewport(){document.documentElement.style.setProperty('--app-height',(window.visualViewport?.height||window.innerHeight)+'px')}
window.visualViewport?.addEventListener('resize',fitViewport);window.addEventListener('resize',fitViewport);fitViewport();

$('#mediaExpand').onclick=()=>{document.body.classList.remove('inspector-expanded');const on=document.body.classList.toggle('media-expanded');$('#mediaExpand').setAttribute('aria-pressed',String(on));requestAnimationFrame(()=>{fitKey='';fit();draw()})};
